P (0,0) (1,0)

M Color "wall_main"   (0.95,0.95,0.95)
M Color "wall_side"   (0.75,0.95,0.75)
M Color "wall_topbot" (0.75,0.85,1.0)
M Color "wall_pillar" (1.0,0.8,0.4)

M Texture "brick" "./resources/textures/diamond.ppm"

S 0 0.0 1.0 "brick" "brick"

# Salle centrale (sens horaire → normales vers intérieur)
W (4,-4) (-4,-4) "brick" 0 -1
W (4,-1) (4,-4) "brick" 0 -1
W (4,4) (4,1) "brick" 0 -1
W (-4,4) (4,4) "brick" 0 -1
W (-4,1) (-4,4) "brick" 0 -1
W (-4,-4) (-4,-1) "brick" 0 -1

# Couloir EST
W (4,1) (10,1) "brick" 0 -1
W (10,1) (10,4) "brick" 0 -1
W (10,4) (16,4) "brick" 0 -1
W (16,4) (16,-4) "brick" 0 -1
W (16,-4) (10,-4) "brick" 0 -1
W (10,-4) (10,-1) "brick" 0 -1
W (10,-1) (4,-1) "brick" 0 -1

# Couloir OUEST
W (-10,1) (-4,1) "brick" 0 -1
W (-10,4) (-10,1) "brick" 0 -1
W (-16,4) (-10,4) "brick" 0 -1
W (-16,-4) (-16,4) "brick" 0 -1
W (-10,-4) (-16,-4) "brick" 0 -1
W (-10,-1) (-10,-4) "brick" 0 -1
W (-4,-1) (-10,-1) "brick" 0 -1

# Couloir NORD
W (-1,4) (-1,10) "brick" 0 -1
W (-4,10) (-1,10) "brick" 0 -1
W (-4,16) (-4,10) "brick" 0 -1
W (4,16) (-4,16) "brick" 0 -1
W (4,10) (4,16) "brick" 0 -1
W (1,10) (4,10) "brick" 0 -1
W (1,4) (1,10) "brick" 0 -1

# Couloir SUD
W (1,-4) (1,-10) "brick" 0 -1
W (4,-10) (1,-10) "brick" 0 -1
W (4,-16) (4,-10) "brick" 0 -1
W (-4,-16) (4,-16) "brick" 0 -1
W (-4,-10) (-4,-16) "brick" 0 -1
W (-1,-10) (-4,-10) "brick" 0 -1
W (-1,-4) (-1,-10) "brick" 0 -1

# Pilier EST
W (12,-1) (14,-1) "wall_pillar" 0 -1
W (14,-1) (14,1) "wall_pillar" 0 -1
W (14,1) (12,1) "wall_pillar" 0 -1
W (12,1) (12,-1) "wall_pillar" 0 -1

# Pilier OUEST
W (-14,-1) (-12,-1) "wall_pillar" 0 -1
W (-12,-1) (-12,1) "wall_pillar" 0 -1
W (-12,1) (-14,1) "wall_pillar" 0 -1
W (-14,1) (-14,-1) "wall_pillar" 0 -1

# Pilier NORD
W (-1,12) (1,12) "wall_pillar" 0 -1
W (1,12) (1,14) "wall_pillar" 0 -1
W (1,14) (-1,14) "wall_pillar" 0 -1
W (-1,14) (-1,12) "wall_pillar" 0 -1

# Pilier SUD
W (1,-12) (-1,-12) "wall_pillar" 0 -1
W (-1,-12) (-1,-14) "wall_pillar" 0 -1
W (-1,-14) (1,-14) "wall_pillar" 0 -1
W (1,-14) (1,-12) "wall_pillar" 0 -1